"""Render Markdown files (write-up parts, blog notes, KB, outline) to standalone HTML files beside them.

Shared script: the code-to-kaizen-blog skill uses it too.

Usage: uv run --with markdown python -I md2html.py <file.md> [<file.md> ...]
"""

import argparse
import html
import pathlib
import sys

import markdown

CSS = """
/* BEGIN brand-kit:preview-css (generated by brand-kit/tools/sync_brand.py; do not edit) */
:root{
--sans:Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, Roboto, Helvetica, Arial, sans-serif;
--mono:ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, "Liberation Mono", "Microsoft YaHei",
    "PingFang SC", "Noto Sans CJK SC", monospace;
--ink:#292929;
--ink-strong:#141414;
--mute:#6b6b6b;
--line:#d9d9d9;
--border:#e9e9e9;
--bg:#ffffff;
--sidebar-bg:#fafafa;
--link:#1a5fb4;
--code-bg:#f6f8fa;
--inline-code-bg:#f2f3f5;
}
/* END brand-kit:preview-css */
body{font-family:var(--sans);font-size:17px;line-height:1.65;color:var(--ink);
background:var(--bg);max-width:860px;margin:40px auto;padding:0 16px}
h1,h2,h3{color:var(--ink-strong);line-height:1.3} h1{font-size:30px}
h2{font-size:23px;margin-top:2em;border-bottom:1px solid var(--border);padding-bottom:4px} h3{font-size:19px}
code{font-family:var(--mono);font-size:.88em;background:var(--inline-code-bg);
padding:1px 4px;border-radius:4px}
pre{background:var(--code-bg);padding:12px 14px;border-radius:8px;overflow-x:auto} pre code{background:none;padding:0}
table{border-collapse:collapse;margin:1em 0;font-size:.92em;display:block;overflow-x:auto}
th,td{border:1px solid var(--border);padding:6px 10px;vertical-align:top} th{background:var(--sidebar-bg)}
blockquote{border-left:3px solid var(--line);margin:1em 0;padding:.2em 1em;color:var(--mute)} a{color:var(--link)}
img{max-width:100%}
"""
HEAD = '<!doctype html><html lang="en"><head><meta charset="utf-8">' \
       '<meta name="viewport" content="width=device-width,initial-scale=1">'


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("files", nargs="+", type=pathlib.Path, help="Markdown files to render")
    a = ap.parse_args()
    failed = 0
    for p in a.files:
        if not p.is_file():
            print(f"error: no such file: {p}", file=sys.stderr)
            failed += 1
            continue
        body = markdown.markdown(p.read_text(encoding="utf-8"),
                                 extensions=["tables", "fenced_code", "sane_lists", "toc"])
        title = html.escape(p.stem.replace("_", " "))
        out = p.with_suffix(".html")
        out.write_text(f"{HEAD}<title>{title}</title><style>{CSS}</style></head><body>{body}</body></html>",
                       encoding="utf-8")
        print("wrote", out)
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())
